void LogViewerScreen::leave_detail() {
  strcpy(_detail_log_file_name, "");
  _detail_log_timestamp.clear();
  _detail_upload_timestamp.clear();
  _detail_log_upload_id = 0;
}

void LogViewerScreen::enter_screen(Controller& controller) {
  leave_detail();
